const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (input) => {
    const [xStr, yStr] = input.trim().split(/\s+/);
    const x = parseInt(xStr, 10);
    const y = parseInt(yStr, 10);

    if (x === y) {
        console.log("No");
    } else if (x < y) {
        if (y - x === 1) {
            console.log("Yes");
        } else {
            console.log("No");
        }
    } else {
        if (y === 0 || y === 1) {
            console.log("No");
        } else {
            let newY = y - 1;
            let newX = x - newY;
            if (newX & 1) {
                console.log("No");
            } else {
                console.log("Yes");
            }
        }
    }
    rl.close();
});

